function vexHtml(ch){var L=VEX[ch];if(!L)return '';
  var vi=['ㅏ','ㅐ','ㅑ','ㅒ','ㅓ','ㅔ','ㅕ','ㅖ','ㅗ','ㅘ','ㅙ','ㅚ','ㅛ','ㅜ','ㅝ','ㅞ','ㅟ','ㅠ','ㅡ','ㅢ','ㅣ'].indexOf(ch),vc=0x1161+vi;
  var h='<table class="tbl"><tr><th>Example</th><th>Meaning</th><th></th></tr>';
  L.forEach(function(x){var out=x[0].split('').map(function(sy){var jm=sy.normalize('NFD');
      if(jm.length!=2||jm.charCodeAt(1)!=vc)return sy;
      var cls='ov-vt';if('ㅗㅛㅜㅠㅡ'.indexOf(ch)>=0)cls='ov-vf';else if('ㅘㅙㅚㅝㅞㅟㅢ'.indexOf(ch)>=0)cls='ov-vm';
      return '<span class="sy">'+sy+'<span class="ov '+cls+'" aria-hidden="true">'+sy+'</span></span>'}).join('');
    h+='<tr><td><b>'+out+'</b> <span class="rom">'+x[1]+'</span></td><td class="mn">'+x[2]+'</td><td class="sp"><button data-say="'+x[0]+'" aria-label="Listen">🔊</button></td></tr>'});
  return h+'</table>'}
function exHtml(ch){var e=EX[ch],h='<div class="tip">Letter name: <b>'+e.name[0]+'</b> <span class="rom">('+e.name[1]+')</span></div><table class="tbl"><tr><th>Position</th><th>Example</th><th>Meaning</th><th></th></tr>';
  ['Start','Middle','End'].forEach(function(lab,i){var x=e.pos[i];
    if(x==="none"){h+='<tr><td>'+lab+'</td><td colspan="3">Not used at the end of a word</td></tr>';return}
    if(!x){h+='<tr><td>'+lab+'</td><td colspan="3">No example yet</td></tr>';return}
    var w=x[0],idx=x[3]!==undefined?x[3]:(i==2?w.length-1:i);
    var tsy=w[idx],jm=tsy.normalize('NFD').split(''),ci=i==2?jm.length-1:0;
    var brk=jm.map(function(q,k){var c=jamoChar(q);return k==ci?'<span class="hl">'+c+'</span>':c}).join(' + ')+' = '+tsy;
    var vc=jm[1].charCodeAt(0),flat=vc>=0x1169&&vc<=0x1174,fin=jm.length>2,cls=i==2?'ov-f':(flat?(fin?'ov-if2':'ov-if'):(fin?'ov-it2':'ov-it'));
    var sy='<span class="sy">'+tsy+'<span class="ov '+cls+'" aria-hidden="true">'+tsy+'</span></span>';
    var wd=w.split('');wd[idx]=sy;
    h+='<tr><td>'+lab+'</td><td><b>'+wd.join('')+'</b> <span class="rom">'+x[1]+'</span></td><td class="mn">'+x[2]+'</td><td class="sp"><button data-say="'+w+'" aria-label="Listen">🔊</button></td></tr>'});
  return h+'</table>'}

function jamoChar(q){var L=['ㄱ','ㄲ','ㄴ','ㄷ','ㄸ','ㄹ','ㅁ','ㅂ','ㅃ','ㅅ','ㅆ','ㅇ','ㅈ','ㅉ','ㅊ','ㅋ','ㅌ','ㅍ','ㅎ'],V=['ㅏ','ㅐ','ㅑ','ㅒ','ㅓ','ㅔ','ㅕ','ㅖ','ㅗ','ㅘ','ㅙ','ㅚ','ㅛ','ㅜ','ㅝ','ㅞ','ㅟ','ㅠ','ㅡ','ㅢ','ㅣ'],T=['','ㄱ','ㄲ','ㄳ','ㄴ','ㄵ','ㄶ','ㄷ','ㄹ','ㄺ','ㄻ','ㄼ','ㄽ','ㄾ','ㄿ','ㅀ','ㅁ','ㅂ','ㅄ','ㅅ','ㅆ','ㅇ','ㅈ','ㅊ','ㅋ','ㅌ','ㅍ','ㅎ'];
  var c=q.charCodeAt(0);
  if(c>=0x1100&&c<=0x1112)return L[c-0x1100];
  if(c>=0x1161&&c<=0x1175)return V[c-0x1161];
  if(c>=0x11A8&&c<=0x11C2)return T[c-0x11A7];
  return q}
