// Build one list of items: {ch, rom, syl, sylRom, kind, strokes[{d,t}], pos, parts, tip}
function xr(b){var lo=1e9,hi=-1e9;b.forEach(function(d){(d.match(/[MHVLCA][^MHVLCA]*/g)||[]).forEach(function(c){var n=c.slice(1).trim().split(/[\s,]+/).map(Number),t=c[0],xs=[];if(t=="M"||t=="L"||t=="H")xs=[n[0]];else if(t=="C")xs=[n[0],n[2],n[4]];else if(t=="A")xs=[n[5]];xs.forEach(function(v){lo=Math.min(lo,v);hi=Math.max(hi,v)})})});return[lo,hi]}
var items=[];
C.forEach(function(c){items.push({ch:c[0],rom:c[1],syl:c[2],sr:c[3],kind:"c",pos:c[4],st:c[5].map(function(d){return{d:d,t:""}}),tip:c[0]=="ㅇ"||c[0]=="ㅎ"?"Draw the circle from the top, turning left.":""})});
D.forEach(function(d){var b=C[d[5]][5],s=[];[0,1].forEach(function(k){b.forEach(function(p){s.push({d:p,t:"translate("+(k?53-.46*xr(b)[0]:47-.46*xr(b)[1])+" 22) scale(.46)"})})});items.push({ch:d[0],rom:d[1],syl:d[2],sr:d[3],kind:"d",pos:d[4],st:s,tip:"Write "+C[d[5]][0]+" two times, side by side. Both are small."})});
V.forEach(function(v,i){items.push({ch:v[0],rom:v[1],syl:v[2],sr:v[3],kind:i<10?"v":"v2",st:v[4].map(function(d){return{d:d,t:""}}),tip:i<10?"":"Same shape as the vowel before it, with one more line."})});
W.forEach(function(w){var g=function(c){return V.filter(function(v){return v[0]==c})[0][4]},t1=w[0]=="ㅢ"?"translate(6 32) scale(.5)":"translate(6 25) scale(.5)",t2=w[0]=="ㅢ"?"translate(28 22) scale(.5)":"translate(34 25) scale(.5)";items.push({ch:w[0],rom:w[1],syl:w[2],sr:w[3],kind:"w",parts:[w[4],w[5]],st:g(w[4]).map(function(d){return{d:d,t:t1}}).concat(g(w[5]).map(function(d){return{d:d,t:t2}})),tip:"Write "+w[4]+" first, then "+w[5]+". Both are small."})});
var byCh={};items.forEach(function(it,i){it.i=i;byCh[it.ch]=it});
var SEQC=items.filter(function(x){return x.kind=="c"}).concat(items.filter(function(x){return x.kind=="d"}));
var SEQV=items.filter(function(x){return x.kind=="v"&&"ㅏㅑㅓㅕㅣ".indexOf(x.ch)>=0}).concat(items.filter(function(x){return x.kind=="v"&&"ㅗㅛㅜㅠㅡ".indexOf(x.ch)>=0}),items.filter(function(x){return x.kind=="v2"}),items.filter(function(x){return x.kind=="w"}));
function seqOf(it){return it.kind=="c"||it.kind=="d"?SEQC:SEQV}
function isOpen(it){var s=seqOf(it),k=s.indexOf(it);return unlockAll||k<1||!!learned[it.ch]||!!learned[s[k-1].ch]}
function navOpen(d){var s=seqOf(cur),k=s.indexOf(cur),n=s.length;for(var j=1;j<n;j++){var t=s[((k+d*j)%n+n)%n];if(isOpen(t)){open(t.i);return}}}
function ubtn(){return tab==0?'<details class="sghow"><summary>How to use this tab</summary><ol><li><span>Two speakers talk: <b>가</b> asks and <b>나</b> answers.</span></li><li><span><b>Round 1:</b> you are <b>나</b>. Answer in Korean (type or 🎤), then tap <b>Check</b>.</span></li><li><span><b>Round 2:</b> roles switch. You are <b>가</b> and you ask. 나 answers you.</span></li><li><span><b>Play:</b> listen to the whole Built-in script. A color light moves down the list.</span></li><li><span><b>Role play:</b> pick 나 or 가. Only the other speaker talks. On your turn the light turns red and the mic listens to you. Tap Done to stop early.</span></li><li><span><b>Move a dialogue:</b> open Built-in questions. Touch and hold any dialogue box for a moment, then drag it up or down (or drag ⋮⋮ right away). The Play order changes too.</span></li><li><span><b>+ Add Q&amp;A:</b> type the Korean question and answer. The English meaning fills in by itself (needs internet). You can change it. Tap the pencil to edit or the trash icon to delete.</span></li><li><span><b>Key word (optional):</b> a word the answer must have. Use | for choices, like 시|살.</span></li></ol></details>':'<details class="sghow"><summary>How to use this tab</summary><ol><li><span>Tap a vowel to open it. It plays the stroke order and the sound for you.</span></li><li><span>Tap <b>Replay</b>, <b>Next stroke</b>, or <b>🔊 Listen</b> to see and hear it again.</span></li><li><span>Tap <b>✏️ Draw it yourself</b> and write each stroke. A vowel you draw is marked <b>Learned ✓</b>.</span></li><li><span>Mixed vowels are two vowels written together. You cannot draw them. Tap the small vowel buttons to open each part.</span></li><li><span><b>Progress:</b> the top bar and count show how many vowels you learned. It saves on this device. Back it up in <b>⚙ Settings</b> with Export.</span></li></ol></details>'}

