function start(d){var m=/M\s*([\d.]+)[ ,]+([\d.]+)/.exec(d);return[+m[1],+m[2]]}
function pad(it){
  var g='<path class="g" d="M50 4V96M4 50H96M4 4L96 96M96 4L4 96" opacity=".6"/>',h='',s='',d='';
  if(!it.st)return '<div class="pad"><svg viewBox="0 0 100 100" aria-hidden="true"><path class="g" d="M50 4V96M4 50H96"/><text x="50" y="68" text-anchor="middle" font-size="58" font-family="var(--serif)" fill="var(--ink)">'+it.ch+'</text></svg></div>';
  it.st.forEach(function(p,i){var o=start(p.d),w=p.t?' transform="'+p.t+'"':'';
    h+='<g'+w+'><path class="gh" d="'+p.d+'"/></g>';
    s+='<g'+w+'><path class="st" pathLength="1" id="s'+i+'" d="'+p.d+'"/></g>';
    d+='<g'+w+'><circle class="dot" id="c'+i+'" cx="'+o[0]+'" cy="'+o[1]+'" r="6.5"/><text class="dt" id="n'+i+'" x="'+o[0]+'" y="'+(o[1]+2.3)+'">'+(i+1)+'</text></g>'});
  return '<div class="pad"><svg viewBox="0 0 100 100" role="img" aria-label="Stroke order of '+it.ch+'"><path class="g" d="M50 4V96M4 50H96"/>'+h+s+d+'<g id="ul"></g></svg></div>';
}
