function area(a){var s=0;for(var i=0;i<a.length;i++){var p=a[i],q=a[(i+1)%a.length];s+=p[0]*q[1]-q[0]*p[1]}return s}
function dens(u){var r=[u[0]];for(var i=1;i<u.length;i++){var a=u[i-1],b=u[i],n=Math.max(1,Math.ceil(dist(a,b)/3));for(var j=1;j<=n;j++)r.push([a[0]+(b[0]-a[0])*j/n,a[1]+(b[1]-a[1])*j/n])}return r}
function samples(k){var p=$("s"+k),m=/translate\(([\d.]+) ([\d.]+)\) scale\(([\d.]+)\)/.exec(cur.st[k].t),tx=m?+m[1]:0,ty=m?+m[2]:0,sc=m?+m[3]:1,L=p.getTotalLength(),r=[];for(var j=0;j<=24;j++){var q=p.getPointAtLength(L*j/24);r.push([q.x*sc+tx,q.y*sc+ty])}return{pts:r,sc:sc}}
function match(k,u){var s=samples(k),e=s.pts,tol=Math.max(10,20*s.sc);
 if(dist(u[0],e[0])>tol*1.3||dist(u[u.length-1],e[24])>tol*1.5)return false;
 for(var i=0;i<e.length;i++){if(!u.some(function(p){return dist(p,e[i])<tol*1.2}))return false}
 var tot=0;for(var j=0;j<u.length;j++){var mn=1e9;for(var i=0;i<e.length;i++)mn=Math.min(mn,dist(u[j],e[i]));if(mn>tol*2)return false;tot+=mn}
 if(tot/u.length>tol*.8)return false;
 if(dist(e[0],e[24])<6&&area(u)*area(e)<0)return false;
 return true}
